'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/buttongroup/md-gb-button-group.js';
import {ButtonGroupElement} from '@material/web/labs/gb/components/buttongroup/button-group-element.js';

/**
 * A Material Design button group. Wraps <md-gb-button-group>.
 * Docs: https://material-web.dev/3.0/components/button-group/
 */
export const MdButtonGroup = createComponent({
  react: React,
  tagName: 'md-gb-button-group',
  elementClass: ButtonGroupElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdButtonGroupProps = React.ComponentProps<typeof MdButtonGroup>;
